<?php require_once __DIR__.'/../includes/functions.php';require_login('hospital');if($_SERVER['REQUEST_METHOD']!=='POST'){redirect('/hospital/index.php');}verify_csrf();$pdo=db();$uid=current_user()['id'];$s=$pdo->prepare("SELECT id FROM hospitals WHERE user_id=? AND status='active'");$s->execute([$uid]);$hospital=$s->fetch();if(!$hospital){flash('No active hospital profile is linked to your account.','error');redirect('/hospital/index.php');}$hid=(int)$hospital['id'];try{$action=$_POST['action']??'';if($action==='complete'){$bid=(int)($_POST['booking_id']??0);$s=$pdo->prepare("SELECT * FROM bookings WHERE id=? AND hospital_id=? AND status='approved'");$s->execute([$bid,$hid]);$b=$s->fetch();if(!$b)throw new RuntimeException('Only approved appointments for your hospital can be marked complete.');$pdo->beginTransaction();$pdo->prepare("UPDATE bookings SET status='completed' WHERE id=?")->execute([$bid]);$pdo->prepare('INSERT INTO vaccination_records(booking_id,child_id,vaccine_id,hospital_id,administered_on,administered_by,notes) VALUES(?,?,?,?,CURDATE(),?,?)')->execute([$bid,$b['child_id'],$b['vaccine_id'],$hid,$uid,trim($_POST['notes']??'')]);$pdo->commit();flash('Vaccination recorded successfully.');}elseif($action==='availability'){$vid=(int)($_POST['vaccine_id']??0);$status=$_POST['status']??'';if(!in_array($status,['available','unavailable'],true))throw new RuntimeException('Invalid availability status.');$s=$pdo->prepare('UPDATE hospital_vaccines SET status=? WHERE hospital_id=? AND vaccine_id=?');$s->execute([$status,$hid,$vid]);flash('Vaccine availability updated.');}else throw new RuntimeException('Unknown action.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e instanceof RuntimeException?$e->getMessage():'Unable to update the record. It may already exist.','error');}redirect('/hospital/index.php');?>
